    "detailedDescription": "O Giclê Calibrado para Refrigeração Pneumática da Agulha é um bico injetor metálico com orifício microscópico de precisão (geralmente entre 0.3 mm e 0.8 mm de diâmetro interno), conectado à linha de ar comprimido da fábrica ou a um microcompressor dedicado. Posicionado a milímetros do trajeto da agulha, ele emite um jato constante ou pulsado de ar em direção ao olho e à lâmina da agulha. Em regimes de produção pesada (bordando lonas grossas, tecidos resinados, feltros ou filmes com adesivo termofusível), o atrito mecânico pode elevar a temperatura da agulha para mais de 250°C em poucos segundos; o giclê refrigerador dissipa esse calor instantaneamente, mantendo a temperatura da agulha abaixo de 80°C.",
