    "shortDescription": "Dispositivo mecânico de aperto manual baseado em manípulo com trava excêntrica de came que permite travar tecidos no bastidor com pressão instantânea, constante e sem esforço de torção.",
    "origin": "Inspirado nos grampos industriais de fixação rápida do tipo 'toggle clamp' da indústria mecânica alemã, adaptado para molduras e bastidores de bordado para acelerar o setup operacional.",
    "detailedDescription": "O Grampo Rápido de Fixação com Excêntrico Articulado substitui ou aprimora os tradicionais parafusos de aperto rotativo dos bastidores de bordado por um sistema de alavanca com eixo excêntrico (came). Ao girar a alavanca de uma posição aberta para a posição travada, o perfil excêntrico converte o movimento angular em deslocamento linear com enorme vantagem mecânica, aplicando uma força de compressão exatamente calibrada entre os aros exterior e interior do bastidor. Esse mecanismo não apenas agiliza drasticamente a troca de peças na linha de produção (reduzindo o tempo de bastidoramento em até 60%), mas também elimina o risco de lesões por esforço repetitivo (LER/DORT) nas mãos dos operadores.",
