    "howToIdentify": "Percebe-se a necessidade do grampo de excêntrico quando a equipe de bastidoramento queixa-se de dores nas mãos causadas por aperto de parafusos de bastidor ou quando o tempo de troca de peças no bastidor é o principal gargalo de produtividade do ateliê.",
