    "detailedDescription": "O Guipure Riscado com Ponto Richelieu e Ilhós Eletrônico representa o ápice da digitalização técnica para rendas sem tecido de suporte. Nessa metodologia, toda a peça é bordada exclusivamente sobre filme duplo ou não-tecido hidrossolúvel pesado. A matriz integra três elementos complexos de engenharia de pontos: uma grade alveolar estrutural de fundo (guipure/fagoting) que garante a amarração de sustentação física da peça; colunas densas de ponto Satin com borda festonada simulando os cortes e ilhas do Richelieu; e pequenas perfurações circulares reforçadas com pontos radiais de ilhós bordado. Após a dissolução da entretela na água morna, a peça revela-se uma renda pura tridimensional, lavável e de alta tenacidade estrutural.",
